-- One-time warrior talent reset for the WoW Forever trees (characters DB)
CREATE TABLE IF NOT EXISTS custom_renown_migrations (name VARCHAR(64) PRIMARY KEY, applied TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
DROP PROCEDURE IF EXISTS renown_warrior_reset;
DELIMITER //
