    DELETE ca FROM character_aura ca JOIN characters c ON c.guid=ca.guid WHERE c.class=1 AND ca.spell IN (12163,12165,12281,12282,12284,12285,12286,12287,12289,12290,12292,12294,12295,12296,12297,12298,12299,12300,12301,12302,12303,12307,12308,12311,12312,12313,12317,12318,12319,12320,12321,12322,12323,12324,12328,12329,12330,12658,12659,12663,12664,12665,12666,12668,12676,12677,12678,12679,12697,12700,12701,12702,12703,12704,12711,12712,12713,12714,12724,12725,12726,12727,12750,12751,12752,12753,12761,12762,12763,12764,12765,12781,12783,12784,12785,12788,12789,12791,12792,12797,12799,12800,12803,12804,12807,12809,12810,12811,12812,12813,12814,12815,12818,12830,12831,12832,12833,12834,12835,12836,12837,12838,12849,12852,12853,12855,12856,12857,12858,12860,12861,12862,12867,12876,12877,12878,12879,12944,12945,12950,12958,12959,12960,12961,12962,12963,12971,12972,12973,12974,12975,12999,13000,13001,13002,13045,13046,13047,13048,16462,16463,16464,16465,16466,16487,16489,16492,16493,16494,16538,16539,16540,16541,16542,20496,20497,20498,20499,20500,20501,20502,20503,20504,20505,21551,21552,21553,23584,23585,23586,23587,23588,23695,23881,23892,23893,23894,23922,23923,23924,23925,45000,45002,45003,45004,45005,45006,45008,45009,45010,45011,45012,45013,45014,45015,45016,45017,45018,45019,45020,45021,45025,45026,45028,45029,45030,45031,45032,45033);
